import{_ as i,M as a,p as d,q as l,R as e,t,N as r,V as h,a3 as o}from"./framework-dd056dd6.js";const c="/images/mtm6302-interactive-blacksmith.png",u={},g=e("h1",{id:"assignment-3-interactive-blacksmith",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#assignment-3-interactive-blacksmith","aria-hidden":"true"},"#"),t(" Assignment 3: Interactive Blacksmith")],-1),p=e("p",null,[e("strong",null,"Course:"),t(" MTM6302 — Web Development with JavaScript"),e("br"),e("strong",null,"Due:"),t(" See the assignment deadline in Brightspace.")],-1),m=e("h2",{id:"your-task",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#your-task","aria-hidden":"true"},"#"),t(" Your task")],-1),f=e("p",null,[e("strong",null,"User action → read and check input → call a game function → update the page.")],-1),b=e("p",null,"Players must be able to play without entering commands in the browser console.",-1),y=e("h2",{id:"getting-started",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#getting-started","aria-hidden":"true"},"#"),t(" Getting started")],-1),w=o("<li>Create a new <strong>public GitHub repository</strong> named <strong><code>A3-Interactive-Blacksmith</code></strong>. Use hyphens in the repository name.</li><li>Clone the new repository and open it in VS Code.</li><li>Copy the files from your completed Assignment 1 into this new project, including <code>index.html</code>, your CSS and JavaScript, and the forge graphics. Copy the project files, not the original repository&#39;s <code>.git</code> folder. Keep your original Assignment 1 repository intact.</li><li>Confirm that the original game works before adding the controls. Keep <code>index.html</code> at the repository root and preserve the relative paths to your styles, script, and images.</li><li>Add and test the requirements below. Commit and push your progress to the new repository.</li><li>Enable GitHub Pages: open <strong>Settings → Pages</strong>, choose <strong>Deploy from a branch</strong>, select <strong>main</strong> and <strong>/(root)</strong>, then select <strong>Save</strong>. Push at least one commit to <code>main</code> before configuring the publishing source.</li>",6),k={href:"https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site",target:"_blank",rel:"noopener noreferrer"},v=o('<p>Create a new repository from your completed files rather than trying to fork your own repository.</p><h2 id="game-rules" tabindex="-1"><a class="header-anchor" href="#game-rules" aria-hidden="true">#</a> Game rules</h2><p>Keep the rules from Assignment 1:</p><table><thead><tr><th>Item</th><th>Rule</th></tr></thead><tbody><tr><td>Starting heat</td><td>20</td></tr><tr><td>Starting sword count</td><td>0</td></tr><tr><td>Heat range</td><td>0–100</td></tr><tr><td>Making one sword</td><td>Requires at least 30 heat; uses 30 heat and adds one sword.</td></tr><tr><td>Too cold</td><td>Heat below 30.</td></tr><tr><td>Ready to forge</td><td>Heat from 30 to below 70.</td></tr><tr><td>Roaring fire</td><td>Heat from 70 to 100; crafting is still allowed.</td></tr></tbody></table><h2 id="requirements" tabindex="-1"><a class="header-anchor" href="#requirements" aria-hidden="true">#</a> Requirements</h2><h3 id="_1-add-heat" tabindex="-1"><a class="header-anchor" href="#_1-add-heat" aria-hidden="true">#</a> 1. Add heat</h3><ul><li>Add a <strong>number input</strong> with a visible, associated label such as <strong>Heat to add</strong>.</li><li>Add an <strong>Add heat</strong> button.</li><li>Read the entered value and convert it to a number before using it in arithmetic.</li><li>Accept positive whole numbers. Reject empty input, zero, negative values, decimal values, and values that cannot be read as a finite number.</li><li>For invalid input, show a clear message on the page and leave the heat and sword count unchanged.</li><li>For valid input, pass the amount to your existing <code>heatForge(amount)</code> function. Keep the maximum heat at 100, even when the requested addition would exceed it.</li><li>Update the heat, forge status, graphics, and action message.</li></ul><p>Use appropriate input attributes such as <code>min=&quot;1&quot;</code> and <code>step=&quot;1&quot;</code>, and check the value in your JavaScript handler. If you use a form&#39;s <code>submit</code> event, account for native browser validation so the required on-page feedback can still be displayed.</p><h3 id="_2-make-a-sword" tabindex="-1"><a class="header-anchor" href="#_2-make-a-sword" aria-hidden="true">#</a> 2. Make a sword</h3><ul><li>Add a <strong>Make sword</strong> button that calls your existing <code>makeSword()</code> function.</li><li>Each click makes exactly one sword when there is at least 30 heat.</li><li>Subtract 30 heat and increase the sword count by one after successful crafting.</li><li>When heat is below 30, display an error message on the page explaining that more heat is needed. Leave both numbers unchanged.</li><li>Keep the button usable when the forge is cold so players can receive this feedback.</li></ul><p>An error here means a visible feedback message. You do not need to use <code>throw new Error()</code> or <code>try...catch</code>.</p><h3 id="_3-reset-the-forge" tabindex="-1"><a class="header-anchor" href="#_3-reset-the-forge" aria-hidden="true">#</a> 3. Reset the forge</h3><ul><li>Add a <strong>Reset forge</strong> button that calls your existing <code>resetForge()</code> function.</li><li>Restore heat to 20 and swords made to zero.</li><li>Clear the heat input and previous feedback messages. For this assignment, reset should leave the feedback area empty rather than display the Assignment 1 starting message.</li><li>Restore the Too cold status, matching CSS class, image, and alternative text.</li><li>Initialize the page in this same starting state when it loads or refreshes.</li></ul><h3 id="_4-connect-and-update-the-interface" tabindex="-1"><a class="header-anchor" href="#_4-connect-and-update-the-interface" aria-hidden="true">#</a> 4. Connect and update the interface</h3><ul><li>Use <code>addEventListener()</code> for the controls. Do not use inline HTML event attributes such as <code>onclick</code>.</li><li>Reuse <code>heatForge()</code>, <code>makeSword()</code>, <code>resetForge()</code>, <code>getForgeStatus()</code>, and <code>updateForge()</code> instead of duplicating the game rules in event handlers.</li><li>Make the small changes needed to your existing reset function and input handling.</li><li>Use real buttons and a labelled input. Ensure any buttons inside a form have the appropriate <code>type</code> so clicks do not unexpectedly reload the page.</li><li>Show feedback on the webpage, not only in the console or an alert box. Clear or replace outdated feedback after the next action.</li><li>Keep heat, sword count, status text, status class, and forge image accurate after every action. Keep only one forge status class active at a time.</li><li>Retain the three supplied forge graphics. Keep controls and feedback readable on narrow and wide screens; a visual redesign is not required.</li></ul><h2 id="plan-your-approach" tabindex="-1"><a class="header-anchor" href="#plan-your-approach" aria-hidden="true">#</a> Plan your approach</h2><p>Add short pseudocode comments to your JavaScript before writing the handlers.</p><p>Build one control at a time. Refer to the Week 9 demo for selecting elements, adding listeners, reading form values, and updating the page.</p><h2 id="test-your-game" tabindex="-1"><a class="header-anchor" href="#test-your-game" aria-hidden="true">#</a> Test your game</h2><p>Start each row from a reset forge unless the row describes a sequence. Check the displayed numbers, message, status, and graphic.</p><table><thead><tr><th>Action</th><th>Expected result</th></tr></thead><tbody><tr><td>Open or refresh the page</td><td>Heat 20; swords 0; Too cold; input and feedback empty.</td></tr><tr><td>Click Make sword immediately</td><td>Heat 20; swords 0; visible insufficient-heat message.</td></tr><tr><td>Enter 10 and click Add heat</td><td>Heat 30; swords 0; Ready to forge.</td></tr><tr><td>Add 10, then click Make sword</td><td>Heat 0; swords 1; Too cold; crafting success message.</td></tr><tr><td>Add 49</td><td>Heat 69; Ready to forge.</td></tr><tr><td>Add 50</td><td>Heat 70; Roaring fire.</td></tr><tr><td>Add 100</td><td>Heat capped at 100; Roaring fire.</td></tr><tr><td>Add 100, then click Make sword four times</td><td>Three swords made; fourth attempt fails; heat 10; swords 3.</td></tr><tr><td>Try empty input, 0, -5, and 2.5 separately</td><td>Clear on-page input feedback; no change to heat or swords.</td></tr><tr><td>Play, then click Reset forge</td><td>Heat 20; swords 0; Too cold graphic; input and feedback cleared.</td></tr></tbody></table><h2 id="scope" tabindex="-1"><a class="header-anchor" href="#scope" aria-hidden="true">#</a> Scope</h2><p>This assessment focuses on Week 9 events and input handling.</p><h2 id="submission" tabindex="-1"><a class="header-anchor" href="#submission" aria-hidden="true">#</a> Submission</h2><ol><li>Complete the requirements and test all three controls.</li><li>Commit and push your final files to <strong><code>A3-Interactive-Blacksmith</code></strong>.</li><li>Wait for GitHub Pages to publish your changes, then open the live site and check that the script, styles, and forge graphics load correctly.</li><li>Submit the link to your <strong>working GitHub Pages website</strong> in Brightspace.</li></ol><p>A typical website address is <code>https://YOUR-GITHUB-USERNAME.github.io/A3-Interactive-Blacksmith/</code>. Use the actual published URL shown in your repository&#39;s Pages settings. Submit the website link, not the repository link. No separate report or video is required.</p><h2 id="assessment-focus" tabindex="-1"><a class="header-anchor" href="#assessment-focus" aria-hidden="true">#</a> Assessment focus</h2><ul><li>Working event listeners and reusable game functions.</li><li>Correct reading, conversion, and validation of the heat input.</li><li>Accurate crafting rules and useful on-page feedback.</li><li>Complete reset behaviour and synchronized forge graphics and values.</li><li>Clear code, short planning comments, and a working published site.</li></ul><h2 id="example-interface" tabindex="-1"><a class="header-anchor" href="#example-interface" aria-hidden="true">#</a> Example interface</h2><p>Use this graphic as a reference for the controls and layout.</p><p><img src="'+c+'" alt="The Tiny Forge interface showing forge heat, sword count, status, a Heat to add number input, and Add heat, Make sword, and Reset forge buttons."></p>',31);function _(x,A){const n=a("RouterLink"),s=a("ExternalLinkIcon");return d(),l("div",null,[g,p,m,e("p",null,[t("Extend your completed "),r(n,{to:"/mtm6302/assignments/blacksmith.html"},{default:h(()=>[t("Blacksmith assignment")]),_:1}),t(" so players can heat the forge, make swords, and reset the game using controls on the webpage. Reuse your existing game functions and add event listeners to connect them to the controls.")]),f,b,y,e("ol",null,[w,e("li",null,[t("Open the published website and test it again. See "),e("a",k,[t("GitHub's publishing instructions"),r(s)]),t(" if needed.")])]),v])}const S=i(u,[["render",_],["__file","interactive-blacksmith.html.vue"]]);export{S as default};
